    std::atomic<int> recordsProcessed;
    std::chrono::steady_clock::time_point startTime;

    bool initializeNLP();
    void processChatFile(const std::string& file_path);
    void cleanAndPreprocessRecord(std::unordered_map<std::string, std::string>& record);
    void analyzeMessage(const std::string& message, double& sentiment_score, std::vector<std::string>& keywords, 
                       std::string& issue_category, double& response_time, int& satisfaction);
    std::vector<std::unordered_map<std::string, std::string>> readCSV(const std::string& file_path);
    std::vector<std::unordered_map<std::string, std::string>> readJSON(const std::string& file_path);
    bool insertIntoDatabase(const std::unordered_map<std::string, std::string>& record);
    void logProgress();
    void generateReports();
    void createDailyReport(const std::vector<std::tuple<std::string, double, int, double, int>>& data);
    void createWeeklyReport(const std::vector<std::tuple<std::string, int>>& data);

public:
    DataAnalyzer(const std::string& data_dir = DEFAULT_DATA_DIR, 
                 const std::string& output_dir = DEFAULT_OUTPUT_DIR,
                 const std::string& db_config = "");
    ~DataAnalyzer();

    void run();
};

DataAnalyzer::DataAnalyzer(const std::string& data_dir, const std::string& output_dir, const std::string& db_config) 
    : dataDir(data_dir), outputDir(output_dir), dbConfigFile(db_config),
      fileProcessed(0), recordsProcessed(0) {

    // Validate directories
    if (!std::filesystem::exists(dataDir)) {
        std::filesystem::create_directory(dataDir);
    }
    if (!std::filesystem::exists(outputDir)) {
        std::filesystem::create_directory(outputDir);
    }

    initializeNLP();
}

DataAnalyzer::~DataAnalyzer() {
    if (dbConn) {
        sqlite3_close(dbConn);
    }
}

bool DataAnalyzer::initializeNLP() {
    // In a real implementation, we would initialize NLP components here
    // For this example, we'll just log and return true
    std::cout << "Initializing NLP components..." << std::endl;
    // Simulate initialization time
    std::this_thread::sleep_for(std::chrono::seconds(2));
    std::cout << "NLP components initialized" << std::endl;
