}

void DataAnalyzer::processChatFile(const std::string& file_path) {
    std::lock_guard<std::mutex> lock(mtx);

    try {
        if (file_path.find(".csv") != std::string::npos) {
            auto data = readCSV(file_path);
            for (auto& record : data) {
                cleanAndPreprocessRecord(record);

                // Perform NLP analysis
                double sentiment_score;
                std::vector<std::string> keywords;
                std::string issue_category;
                double response_time;
                int satisfaction;
                analyzeMessage(record["message"], sentiment_score, keywords, issue_category, response_time, satisfaction);

                // Prepare data for database insertion
                std::unordered_map<std::string, std::string> chat_data = {
                    {"chat_id", record["chat_id"]},
                    {"customer_id", record["customer_id"]},
                    {"agent_id", record["agent_id"]},
                    {"timestamp", record["timestamp"]},
                    {"message", record["message"]},
                    {"sentiment_score", std::to_string(sentiment_score)},
                    {"keywords", "dummy"},
                    {"issue_category", issue_category},
                    {"response_time", std::to_string(response_time)},
                    {"customer_satisfaction", std::to_string(satisfaction)}
                };

                insertIntoDatabase(chat_data);
            }
        } else if (file_path.find(".json") != std::string::npos) {
            auto data = readJSON(file_path);
            for (auto& record : data) {
                cleanAndPreprocessRecord(record);

                // Perform NLP analysis
                double sentiment_score;
                std::vector<std::string> keywords;
                std::string issue_category;
                double response_time;
                int satisfaction;
                analyzeMessage(record["message"], sentiment_score, keywords, issue_category, response_time, satisfaction);

                // Prepare data for database insertion
                std::unordered_map<std::string, std::string> chat_data = {
                    {"chat_id", record["chat_id"]},
                    {"customer_id", record["customer_id"]},
                    {"agent_id", record["agent_id"]},
                    {"timestamp", record["timestamp"]},
                    {"message", record["message"]},
                    {"sentiment_score", std::to_string(sentiment_score)},
                    {"keywords", "dummy"},
                    {"issue_category", issue_category},
                    {"response_time", std::to_string(response_time)},
                    {"customer_satisfaction", std::to_string(satisfaction)}
                };

                insertIntoDatabase(chat_data);
            }
        } else {
            std::cout << "Unsupported file format: " << file_path << std::endl;
            return;
        }

        fileProcessed++;
        recordsProcessed++;
        logProgress();
    } catch (const std::exception& e) {
        std::cerr << "Error processing file " << file_path << ": " << e.what() << std::endl;
    }
}

void DataAnalyzer::cleanAndPreprocessRecord(std::unordered_map<std::string, std::string>& record) {
    // Clean timestamp if present
    if (record.find("timestamp") != record.end()) {
        std::string timestamp = record["timestamp"];
        if (!timestamp.empty()) {
            // Try to parse different timestamp formats
            bool parsed = false;
            for (const auto& fmt : {
                "%Y-%m-%d %H:%M:%S", 
                "%Y-%m-%d %H:%M", 
                "%Y-%m-%d", 
                "%d/%m/%Y %H:%M:%S"
            }) {
                try {
                    std::istringstream iss(timestamp);
                    std::chrono::system_clock::time_point tp;
                    tp = std::chrono::system_clock::from_time_t(0); // Initialize to epoch

                    // Parse the date string
                    std::tm t = {};
                    char* result = std::strptime(timestamp.c_str(), fmt.c_str(), &t);
                    if (result && result != timestamp.c_str()) {
                        tp = std::chrono::system_clock::from_time_t(std::mktime(&t));
                        record["timestamp"] = std::chrono::system_clock::to_time_t(tp);
                        parsed = true;
                        break;
                    }
                } catch (...) {
                    continue;
                }
            }
            if (!parsed) {
                // If none of the formats work, keep original string
                // record["timestamp"] = timestamp; // We keep the original format
            }
        }
    }

    // Clean and preprocess message if present
    if (record.find("message") != record.end()) {
        std::string message = record["message"];
        if (!message.empty()) {
            message = textPreprocessor.removeSpecialChars(message);
            message = textPreprocessor.normalizeText(message);
            message = textPreprocessor.removeStopwords(message);
            record["message"] = message;
        }
    }
}

void DataAnalyzer::analyzeMessage(const std::string& message, double& sentiment_score, 
                                 std::vector<std::string>& keywords, std::string& issue_category, 
                                 double& response_time, int& satisfaction) {
    // Mock implementation for demonstration
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_real_distribution<> irr(-1.0, 1.0);
    std::uniform_real_distribution<> irr2(1.0, 300.0);
    std::uniform_int_distribution<> irr3(1, 5);

    sentiment_score = irr(gen);
    keywords = {"keyword1", "keyword2"};
    issue_category = "General Inquiry";
    response_time = irr2(gen);
    satisfaction = irr3(gen);
}

std::vector<std::unordered_map<std::string, std::string>> DataAnalyzer::readCSV(const std::string& file_path) {
    std::ifstream file(file_path);
    std::vector<std::unordered_map<std::string, std::string>> data;

    if (!file.is_open()) {
        std::cerr << "Error opening CSV file: " << file_path << std::endl;
        return data;
    }

    std::string line;
    std::vector<std::string> headers;

    // Read headers
    if (std::getline(file, line)) {
        std::stringstream ss(line);
        std::string item;
        while (std::getline(ss, item, ',')) {
            headers.push_back(item);
        }
    }

    // Read rows
    while (std::getline(file, line)) {
        std::stringstream ss(line);
        std::string item;
        std::unordered_map<std::string, std::string> row;
        int i = 0;
        while (std::getline(ss, item, ',')) {
            if (i < headers.size()) {
                row[headers[i]] = item;
                i++;
            }
        }
        data.push_back(row);
    }

    return data;
}

std::vector<std::unordered_map<std::string, std::string>> DataAnalyzer::readJSON(const std::string& file_path) {
    std::ifstream file(file_path);
    std::vector<std::unordered_map<std::string, std::string>> data;

    if (!file.is_open()) {
        std::cerr << "Error opening JSON file: " << file_path << std::endl;
        return data;
    }

    Json::Reader reader;
    Json::Value root;

    std::string jsonStr;
    std::string line;
    while (std::getline(file, line)) {
        jsonStr += line;
    }

    if (!reader.parse(jsonStr, root, false)) {
        std::cerr << "Error parsing JSON: " << reader.get_error() << std::endl;
        return data;
    }

    // Assuming JSON array format
    if (root.isArray()) {
        for (const auto& elem : root) {
            std::unordered_map<std::string, std::string> record;
            for (const auto& member : elem.getMemberNames()) {
                if (elem[member].isString()) {
                    record[member] = elem[member].asString();
                }
            }
            data.push_back(record);
        }
    } else {
        // Single object case
        for (const auto& member : root.getMemberNames()) {
            if (root[member].isString()) {
                record[member] = root[member].asString();
            }
        }
        data.push_back(record);
    }

    return data;
}

bool DataAnalyzer::insertIntoDatabase(const std::unordered_map<std::string, std::string>& record) {
    if (!dbConn) {
        std::cerr << "Database connection not established." << std::endl;
        return false;
    }

    const char* sql = "INSERT INTO customer_service_chat (chat_id, customer_id, agent_id, timestamp, message, "
                      "sentiment_score, keywords, issue_category, response_time, customer_satisfaction) "
                      "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)";

    sqlite3_stmt* stmt;

    if (sqlite3_prepare_v2(dbConn, sql, -1, &stmt, nullptr) != SQLITE_OK) {
        std::cerr << "Error preparing statement: " << sqlite3_errmsg(dbConn) << std::endl;
        return false;
    }

    sqlite3_bind_text(stmt, 1, record["chat_id"].c_str(), -1, SQLITE_STATIC);
    sqlite3_bind_text(stmt, 2, record["customer_id"].c_str(), -1, SQLITE_STATIC);
    sqlite3_bind_text(stmt, 3, record["agent_id"].c_str(), -1, SQLITE_STATIC);
    sqlite3_bind_text(stmt, 4, record["timestamp"].c_str(), -1, SQLITE_STATIC);
    sqlite3_bind_text(stmt, 5, record["message"].c_str(), -1, SQLITE_STATIC);
    sqlite3_bind_double(stmt, 6, std::stod(record["sentiment_score"]));
    sqlite3_bind_text(stmt, 7, record["keywords"].c_str(), -1, SQLITE_STATIC);
    sqlite3_bind_text(stmt, 8, record["issue_category"].c_str(), -1, SQLITE_STATIC);
    sqlite3_bind_double(stmt, 9, std::stod(record["response_time"]));
    sqlite3_bind_int(stmt, 10, std::stoi(record["customer_satisfaction"]));

    int result = sqlite3_step(stmt);

    sqlite3_finalize(stmt);

    return (result == SQLITE_DONE);
}

void DataAnalyzer::logProgress() {
    if (startTime == std::chrono::steady_clock::time_point()) {
        startTime = std::chrono::steady_clock::now();
    }

    auto now = std::chrono::steady_clock::now();
    auto elapsed = std::chrono::duration_cast<std::chrono::seconds>(now - startTime).count();

    std::cout << "Progress: " << fileProcessed << " files, " << recordsProcessed << " records processed in " 
              << elapsed << " seconds" << std::endl;
}

