void DataAnalyzer::run() {
    try {
        // Connect to SQLite database
        if (sqlite3_open(DB_CONFIG_FILE.c_str(), &dbConn) != SQLITE_OK) {
            std::cerr << "Cannot open database: " << sqlite3_errmsg(dbConn) << std::endl;
            return;
        }

        // Create table if not exists
        const char* createTableSQL = "CREATE TABLE IF NOT EXISTS customer_service_chat ("
                                     "chat_id TEXT PRIMARY KEY, "
                                     "customer_id TEXT, "
                                     "agent_id TEXT, "
                                     "timestamp TEXT, "
                                     "message TEXT, "
                                     "sentiment_score REAL, "
                                     "keywords TEXT, "
                                     "issue_category TEXT, "
                                     "response_time REAL, "
                                     "customer_satisfaction INTEGER)";

        if (sqlite3_exec(dbConn, createTableSQL, nullptr, nullptr, nullptr) != SQLITE_OK) {
            std::cerr << "Error creating table: " << sqlite3_errmsg(dbConn) << std::endl;
            sqlite3_close(dbConn);
            return;
        }

        // Find all files in data directory
        std::vector<std::string> files;
        for (const auto& entry : std::filesystem::directory_iterator(dataDir)) {
            if (entry.path().extension() == ".csv" || entry.path().extension() == ".json") {
                files.push_back(entry.path().string());
            }
        }

        if (files.empty()) {
            std::cout << "No files found in directory: " << dataDir << std::endl;
            sqlite3_close(dbConn);
            return;
        }

        std::cout << "Found " << files.size() << " files to process" << std::endl;

        // Process files with thread pool
        std::vector<std::thread> threads;
        for (const auto& file : files) {
            threads.push_back(std::thread(&DataAnalyzer::processChatFile, this, file));
        }

        for (auto& thread : threads) {
            thread.join();
        }

        // Generate reports
        generateReports();

        // Close database connection
        sqlite3_close(dbConn);
    } catch (const std::exception& e) {
        std::cerr << "Error in main execution: " << e.what() << std::endl;
        if (dbConn) {
            sqlite3_close(dbConn);
        }
    }
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        std::cout << "Usage: " << argv[0] << " [options]" << std::endl;
        std::cout << "Options:" << std::endl;
        std::cout << "  --data_dir <dir>       Input data directory" << std::endl;
        std::cout << "  --output_dir <dir>     Output directory" << std::endl;
        std::cout << "  --db_config <file>     Database configuration file" << std::endl;
        return 1;
    }

    DataAnalyzer analyzer;

    for (int i = 1; i < argc; i++) {
        if (std::string(argv[i]) == "--data_dir") {
            if (i + 1 < argc) {
                analyzer.dataDir = argv[i + 1];
                i++;
            }
        } else if (std::string(argv[i]) == "--output_dir") {
            if (i + 1 < argc) {
                analyzer.outputDir = argv[i + 1];
                i++;
            }
        } else if (std::string(argv[i]) == "--db_config") {
            if (i + 1 < argc) {
                analyzer.dbConfigFile = argv[i + 1];
                i++;
            }
        }
    }

    analyzer.run();

    return 0;
}
