// Constants for default directory paths
const std::string DEFAULT_DATA_DIR = "./data";
const std::string DEFAULT_OUTPUT_DIR = "./reports";
const std::string DB_CONFIG_FILE = "db_config.json";

// Forward declaration of DataPreprocessor class
class DataPreprocessor;

/**
 * @class DataPreprocessor
 * @brief Handles text preprocessing and cleaning tasks
 * @details This class provides functionality for cleaning, normalizing, and analyzing text data
 *          including removing special characters, normalizing case, and removing stopwords
 */
class DataPreprocessor {
private:
    std::set<std::string> stopwords;       // Set to store stopwords for text cleaning
    std::string language;                   // Language setting for text processing

    /**
     * @brief Loads stopwords based on language
     * @details This function populates the stopwords set with appropriate words for the specified language
     */
    void loadStopwords();

public:
    // Constructor for DataPreprocessor
    DataPreprocessor(const std::string& lang = "english");

    // Destructor for DataPreprocessor
    ~DataPreprocessor();

    /**
     * @brief Removes special characters from text
     * @param text Input text to clean
     * @return Cleaned text with only alphanumeric characters and spaces
     */
    std::string removeSpecialChars(const std::string& text);

    /**
     * @brief Normalizes text by converting to lowercase and removing extra spaces
     * @param text Input text to normalize
     * @return Normalized text
     */
    std::string normalizeText(const std::string& text);

    /**
     * @brief Removes stopwords from text
     * @param text Input text with potential stopwords
     * @return Text with stopwords removed
     */
    std::string removeStopwords(const std::string& text);

    /**
     * @brief Tokenizes text into words
     * @param text Input text to tokenize
     * @return Vector of tokens (words) from the text
     */
    std::vector<std::string> tokenizeText(const std::string& text);
};

/**
 * @class DataAnalyzer
 * @brief Main class for analyzing enterprise data
 * @details This class orchestrates the entire data analysis process including file processing, 
 *          data cleaning, NLP analysis, database operations, and report generation
 */
class DataAnalyzer {
private:
    std::string dataDir;                   // Input data directory
    std::string outputDir;                  // Output directory for reports
    std::string dbConfigFile;               // Database configuration file
    DataPreprocessor textPreprocessor;      // Text preprocessing component
    sqlite3* dbConn;                       // SQLite database connection
    std::mutex mtx;                        // Mutex for thread safety
    std::condition_variable cv;             // Condition variable for synchronization
    std::atomic<int> fileProcessed;         // Number of files processed
    std::atomic<int> recordsProcessed;      // Number of records processed
    std::chrono::steady_clock::time_point startTime; // Start time of processing

    /**
     * @brief Initializes NLP components (placeholder for real implementation)
     * @return True if initialization successful, false otherwise
     */
    bool initializeNLP();

    /**
     * @brief Processes a chat file (CSV or JSON)
     * @param file_path Path to the file to process
     */
    void processChatFile(const std::string& file_path);

    /**
     * @brief Cleans and preprocesses a record
     * @param record Reference to the record to clean
     */
    void cleanAndPreprocessRecord(std::unordered_map<std::string, std::string>& record);

    /**
     * @brief Performs NLP analysis on a message
     * @param message Input message to analyze
     * @param sentiment_score Output parameter for sentiment score
     * @param keywords Output parameter for detected keywords
