/**
 * @brief loadStopwords implementation
 * @details Loads stopwords based on specified language
 */
void DataPreprocessor::loadStopwords() {
    if (language == "english") {
        // Simple set of English stopwords for demonstration
        std::string stopwordList = "i me my myself we our ours ourselves you youre youve youll youd your yours yourself yourselves "
                                   "he him his himself she her hers herself it its itself they them their theirs themselves "
                                   "what which who whom this that these those am is are was were be been being have has had having "
                                   "do does did doing a an the and but if or because as until while before after so too such than by "
                                   "with at from of off about once twice against between into through during before after above below "
                                   "to for with by about against between";
        std::istringstream iss(stopwordList);
        std::string word;
        while (iss >> word) {
            stopwords.insert(word);
        }
    } else {
        // Placeholder for other languages
        // In a real implementation, this would load stopwords for other languages
    }
}

/**
 * @brief removeSpecialChars implementation
 * @param text Input text to clean
 * @return Cleaned text with only alphanumeric characters and spaces
 */
std::string DataPreprocessor::removeSpecialChars(const std::string& text) {
    if (text.empty()) return text;

    std::string cleaned;
    for (char c : text) {
        if (std::isalnum(c) || c == ' ') {
            cleaned += c;
        }
    }
    return cleaned;
}

/**
 * @brief normalizeText implementation
 * @param text Input text to normalize
 * @return Normalized text with consistent case and spacing
 */
std::string DataPreprocessor::normalizeText(const std::string& text) {
    if (text.empty()) return text;

    std::string normalized;
    for (char c : text) {
        normalized += std::tolower(c);
    }
    // Replace multiple spaces with single space
    std::string result;
    bool prevSpace = false;
    for (char c : normalized) {
        if (c == ' ') {
            if (!prevSpace) {
                result += c;
                prevSpace = true;
            }
        } else {
            result += c;
            prevSpace = false;
        }
    }
    return result;
}

/**
 * @brief removeStopwords implementation
 * @param text Input text with potential stopwords
 * @return Text with stopwords removed
 */
std::string DataPreprocessor::removeStopwords(const std::string& text) {
    if (text.empty()) return text;

    std::istringstream iss(text);
    std::string word;
    std::string result;
    bool first = true;

    while (iss >> word) {
        if (stopwords.find(word) == stopwords.end()) {
            if (!first) {
                result += " ";
            }
            result += word;
            first = false;
        }
    }

    return result;
}

/**
 * @brief tokenizeText implementation
 * @param text Input text to tokenize
 * @return Vector of tokens (words) from the text
 */
std::vector<std::string> DataPreprocessor::tokenizeText(const std::string& text) {
    if (text.empty()) return {};

    std::istringstream iss(text);
    std::string word;
    std::vector<std::string> tokens;
    while (iss >> word) {
        tokens.push_back(word);
    }
    return tokens;
}

