/**
 * @brief readCSV implementation
 * @param file_path Path to the CSV file
 * @return Vector of records (each record is a map of column names to values)
 */
std::vector<std::unordered_map<std::string, std::string>> DataAnalyzer::readCSV(const std::string& file_path) {
    std::ifstream file(file_path);
    std::vector<std::unordered_map<std::string, std::string>> records;

    if (!file.is_open()) {
        throw std::runtime_error("Cannot open file: " + file_path);
    }

    // Read header to get column names
    std::string header;
    std::getline(file, header);
    std::stringstream ss(header);
    std::string column;
    std::vector<std::string> headers;

    while (std::getline(ss, column, ',')) {
        headers.push_back(column);
    }

    // Read each row
    while (std::getline(file, header, '\n')) {
        std::stringstream ss(header);
        std::unordered_map<std::string, std::string> record;
        for (size_t i = 0; i < headers.size(); i++) {
            std::string value;
            std::getline(ss, value, ',');
            record[headers[i]] = value;
        }
        records.push_back(record);
    }

    return records;
}

/**
 * @brief readJSON implementation
 * @param file_path Path to the JSON file
 * @return Vector of records (each record is a map of column names to values)
 */
std::vector<std::unordered_map<std::string, std::string>> DataAnalyzer::readJSON(const std::string& file_path) {
    std::ifstream file(file_path);
    if (!file.is_open()) {
        throw std::runtime_error("Cannot open JSON file: " + file_path);
    }

    std::stringstream ss;
    ss << file.rdbuf();
    std::string json_string = ss.str();

    // Simple JSON parsing - in a real application, use a proper JSON parser
    // This is a very basic implementation for demonstration purposes
    std::vector<std::unordered_map<std::string, std::string>> records;

    // Find the start of the JSON array
    size_t start_pos = json_string.find('[');
    if (start_pos == std::string::npos) {
        throw std::runtime_error("Invalid JSON format - no array found");
    }

    // Remove the array wrapper and parse individual JSON objects
    std::string json_array = json_string.substr(start_pos + 1, json_string.size() - start_pos - 2);

    // Split the array into individual JSON objects
    size_t obj_start = 0;
    while (obj_start < json_array.size()) {
        size_t obj_end = json_array.find('}', obj_start);
        if (obj_end == std::string::npos) break;

        std::string json_object = json_array.substr(obj_start, obj_end - obj_start + 1);
        obj_start = obj_end + 1;

        // Parse the JSON object into key-value pairs
        std::unordered_map<std::string, std::string> record;
        size_t key_start = json_object.find('"') + 1;
        size_t key_end = json_object.find('"', key_start);
        std::string key = json_object.substr(key_start, key_end - key_start);

        size_t value_start = key_end + 3; // account for colon and space
        size_t value_end = json_object.find(',', value_start);
        if (value_end == std::string::npos) value_end = json_object.find('}', value_start);
        std::string value = json_object.substr(value_start, value_end - value_start);

        record[key] = value;
        records.push_back(record);
    }

    return records;
}

/**
 * @brief insertIntoDatabase implementation
 * @param record Record to insert
 * @return True if insertion successful, false otherwise
 */
bool DataAnalyzer::insertIntoDatabase(const std::unordered_map<std::string, std::string>& record) {
    // Prepare SQL statement
    std::string sql = "INSERT INTO customer_service_chat (";
    std::vector<std::string> columns;
    std::vector<std::string> values;

    for (const auto& pair : record) {
        columns.push_back(pair.first);
        values.push_back("'" + pair.second + "'");
    }

    sql += (columns.join(", ") + " VALUES (" + values.join(", ") + ")");

    // Execute SQL statement
    char* errMsg = nullptr;
    int rc = sqlite3_exec(dbConn, sql.c_str(), nullptr, nullptr, &errMsg);

    if (rc != SQLITE_OK) {
        std::cerr << "SQL error: " << errMsg << std::endl;
        sqlite3_free(errMsg);
        return false;
    }

    return true;
}

