### 4. 欠損値の処理関数
```cpp
vector<vector<string>> handleMissingValues(vector<vector<string>>& data, const vector<int>& columns, const string& strategy) {
    if (data.empty() || columns.empty()) return data;

    // 各列について処理
    for (int col : columns) {
        if (col < 0 || col >= data[0].size()) continue;

        if (strategy == "drop") {
            // 欠損値のある行を削除
            vector<vector<string>> newData;
            for (const auto& row : data) {
                if (!row[col].empty()) {  // セルが空でない場合のみ
                    newData.push_back(row);
                }
            }
            data = newData;
        } else if (strategy == "fill") {
            // 最頻値で埋める（例: 文字列列は最初の出現する値で、数値列は中央値で）
            // ここでは簡単のため、最初の出現する値で埋めます

            // 最頻値を計算
            map<string, int> valueCount;
            for (const auto& row : data) {
                if (!row[col].empty()) {
                    valueCount[row[col]]++;
                }
            }

            // 最頻値を取得（同じ場合は最初のものを使用）
            string mode;
            int maxCount = 0;
            for (const auto& pair : valueCount) {
                if (pair.second > maxCount) {
                    mode = pair.first;
                    maxCount = pair.second;
                }
            }

            // 欠損値を埋める
            for (auto& row : data) {
                if (row[col].empty()) {
                    row[col] = mode;
                }
            }
        }
    }

    return data;
}
```
- 欠損値を処理する関数です。
- `drop`戦略では、欠損値のある行を削除します。
- `fill`戦略では、最頻値で欠損値を埋めます。
- 最頻値の計算と埋め方のロジックを追加しました。

