    AnalysisResult calculateChatMetrics(const vector<ChatLog>& chat_data) {
        AnalysisResult result;
        result.total_chats = chat_data.size();

        // Calculate average response time
        double total_time = 0.0;
        for (const auto& log : chat_data) {
            total_time += log.duration;
        }
        result.avg_response_time = total_time / result.total_chats;

        // Calculate satisfaction distribution
        map<int, int> satisfaction_count;
        for (const auto& log : chat_data) {
            satisfaction_count[log.satisfaction]++;
        }
        result.satisfaction_distribution = satisfaction_count;

