        // Top 5 issues
        vector<pair<string, int>> temp;
        for (const auto& entry : issue_count) {
            temp.push_back(entry);
        }
        sort(temp.begin(), temp.end(), [](const auto& a, const auto& b) {
            return a.second > b.second;
        });
        result.top_issues = vector<pair<string, int>>(temp.begin(), temp.begin() + min(5, (int)temp.size()));

        return result;
    }

