            return a.second > b.second;
        });

        // Select top 5 issues
        result.top_issues = vector<pair<string, int>>(temp.begin(), temp.begin() + min(5, (int)temp.size()));

        return result;
    }

    // Aggregate transaction data
    SalesData aggregateTransactions(const vector<TransactionRecord>& records) {
        // Group transactions by date based on analysis depth
        map<time_period, vector<double>> grouped;
        for (const auto& record : records) {
            // Simplified time grouping - in reality, this would be more complex
            time_period key = record.timestamp.date();
            grouped[key].push_back(record.amount);
        }

        // Calculate total sales per day
        SalesData result;
        for (const auto& entry : grouped) {
            result.date = entry.first;
            result.sales_amount = accumulate(entry.second.begin(), entry.second.end(), 0.0);
            result.purchases = entry.second.size();
        }
        return result;
    }

    // Save analysis results to a file
    void saveAnalysisResult(const AnalysisResult& result, const string& type) {
        // Open output file
        ofstream file;
        file.open(getOutputFilename(type), ios::app);

        // Write results to file
        file << "Analysis result for " << type << ":\n";
        file << "Avg response time: " << result.avg_response_time << " seconds\n";
        file << "Total chats: " << result.total_chats << "\n";

        // Write satisfaction distribution
        file << "Satisfaction distribution:\n";
        for (const auto& entry : result.satisfaction_distribution) {
            file << "Rating " << entry.first << ": " << entry.second << " chats\n";
        }

        // Write top issues
        file << "\nTop issues:\n";
        for (const auto& issue : result.top_issues) {
            file << issue.first << " (" << issue.second << " mentions)\n";
        }

        // Close file
        file.close();
    }

    // Generate appropriate filename for output
    string getOutputFilename(const string& type) {
        // Create timestamp for filename
        time_duration td = seconds(10); // Example timestamp
        return currentConfig.output_dir + "/" + type + "_" + to_string(td.hours()) + "_" + to_string(td.minutes()) + ".txt";
    }

